class Solution {
public:
    vector<int> missingRolls(vector<int>& rolls, int mean, int n) {
        int m = rolls.size();
        int sum_rolls = 0;
        for (int x : rolls) sum_rolls += x;
        int total_sum = mean * (m + n);
        int missing_sum = total_sum - sum_rolls;
        if (missing_sum < n || missing_sum > 6 * n) return {};
        int base = missing_sum / n;
        int rem = missing_sum % n;
        vector<int> res(n, base);
        for (int i = 0; i < rem; ++i) res[i]++;
        return res;
    }
};

class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int m = rolls.length;
        int sumRolls = 0;
        for (int x : rolls) sumRolls += x;
        int totalSum = mean * (m + n);
        int missingSum = totalSum - sumRolls;
        if (missingSum < n || missingSum > 6 * n) return new int[0];
        int base = missingSum / n;
        int rem = missingSum % n;
        int[] res = new int[n];
        Arrays.fill(res, base);
        for (int i = 0; i < rem; i++) res[i]++;
        return res;
    }
}

var missingRolls = function(rolls, mean, n) {
  const m = rolls.length;
  const sumRolls = rolls.reduce((a, b) => a + b, 0);
  const totalSum = mean * (m + n);
  const missingSum = totalSum - sumRolls;
  if (missingSum < n || missingSum > 6 * n) return [];
  const base = Math.floor(missingSum / n);
  const rem = missingSum % n;
  const res = new Array(n).fill(base);
  for (let i = 0; i < rem; i++) res[i]++;
  return res;
};
